	for lo < hi {
		mid := lo + (hi-lo)/2
		if nums[mid] == target {
			return mid
		}
		if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return -1
}

func dfs(graph [][]int, start int, visit func(int)) {
	stack := []int{start}
	seen := make([]bool, len(graph))
	for len(stack) > 0 {
		node := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if seen[node] {
			continue
		}
		seen[node] = true
		visit(node)
		for i := len(graph[node]) - 1; i >= 0; i-- {
			next := graph[node][i]
			if !seen[next] {
				stack = append(stack, next)
			}
		}
	}
}

func bfs(graph [][]int, start int, visit func(int)) {
	queue := []int{start}
	seen := make([]bool, len(graph))
	seen[start] = true
	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]
		visit(node)
		for _, next := range graph[node] {
			if !seen[next] {
				seen[next] = true
				queue = append(queue, next)
			}
		}
	}
}

func twoSumSorted(nums []int, target int) (int, int) {
	left, right := 0, len(nums)-1
	for left < right {
		sum := nums[left] + nums[right]
		if sum == target {
			return left, right
		}
		if sum < target {
			left++
		} else {
			right--
		}
	}
	return 0, 0
}

func isValidParentheses(input string) bool {
	stack := make([]rune, 0)
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	for _, ch := range input {
		switch ch {
		case '(', '[', '{':
			stack = append(stack, ch)
		case ')', ']', '}':
			if len(stack) == 0 || stack[len(stack)-1] != pairs[ch] {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	return len(stack) == 0
}

func climbStairs(n int) int {
	if n <= 2 {
		return n
	}
	prev, curr := 1, 2
	for i := 3; i <= n; i++ {
		next := prev + curr
		prev = curr
		curr = next
	}
	return curr
}

func mergeSorted(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	out = append(out, b[j:]...)
	return out
}

func quickselect(nums []int, k int) int {
	left, right := 0, len(nums)-1
	for {
		pivot := nums[right]
		store := left
		for i := left; i < right; i++ {
			if nums[i] < pivot {
				nums[i], nums[store] = nums[store], nums[i]
				store++
			}
		}
		nums[store], nums[right] = nums[right], nums[store]
		if store == k {
			return nums[store]
		}
		if k < store {
			right = store - 1
		} else {
			left = store + 1
		}
	}
}
